const tone = (s:string) => s==="Confirmed"||s==="Paid"||s==="Active"||s==="Successful"||s==="Approved"||s==="Refunded"?"success":s==="Pending"||s==="Requested"?"warning":s==="Cancelled"||s==="Failed"||s==="Rejected"?"danger":"neutral" as const;

export function BookingsPage(){return <><PageIntro title="Booking Management" description="Search, review, and manage every reservation." actions={<Button><Plus/>New Booking</Button>}/><FilterBar fields={["Booking ID","Customer","Hotel","Check-in date","Check-out date","Booking status"]}/><Card><CardHead title="Bookings" subtitle="2,845 reservations"/><TableWrap><thead><tr>{["Booking ID","Customer","Hotel / Room","Dates","Guests","Amount","Payment","Status","Actions"].map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody>{rows.map(r=><tr key={r[0]} className="hover:bg-muted/30"><Td className="font-medium">{r[0]}</Td><Td>{r[1]}</Td><Td><b className="block font-medium">{r[2]}</b><small className="text-muted-foreground">{r[3]}</small></Td><Td>{r[4]}</Td><Td>{r[5]}</Td><Td className="font-medium">{r[6]}</Td><Td><StatusBadge tone={tone(r[7])}>{r[7]}</StatusBadge></Td><Td><StatusBadge tone={tone(r[8])}>{r[8]}</StatusBadge></Td><Td><div className="flex gap-1"><Button variant="ghost" size="sm">View</Button><Button variant="ghost" size="sm">Edit</Button><CancelDialog/><Button variant="ghost" size="icon" aria-label="Download invoice"><Download/></Button></div></Td></tr>)}</tbody></TableWrap><Pagination/></Card></>}
function CancelDialog(){return <Dialog><DialogTrigger asChild><Button variant="ghost" size="sm" className="text-destructive">Cancel</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Cancel this booking?</DialogTitle><DialogDescription>This releases the room inventory and starts the applicable refund process.</DialogDescription></DialogHeader><DialogFooter><DialogClose asChild><Button variant="outline">Keep booking</Button></DialogClose><DialogClose asChild><Button variant="destructive">Cancel booking</Button></DialogClose></DialogFooter></DialogContent></Dialog>}

