export function AvailabilityPage(){const dates=["Sep 20","Sep 21","Sep 22","Sep 23","Sep 24","Sep 25","Sep 26"];return <><PageIntro title="Availability" description="Update inventory and manage room blocks across properties." actions={<><Button variant="outline"><CalendarDays/>Select dates</Button><BlockDialog/></>}/><FilterBar fields={["Hotel","Room type"]}/><Card><CardHead title="Room Availability" subtitle="Grand Palace Hotel · September 2026"/><TableWrap><thead><tr><Th>Room Type</Th>{dates.map(d=><Th key={d}>{d}</Th>)}<Th>Action</Th></tr></thead><tbody>{[["Deluxe Room",12,10,8,15,14,9,7],["Executive Room",6,5,7,8,9,6,4],["Suite",3,2,2,4,3,1,0]].map(r=><tr key={r[0]}><Td className="font-medium">{r[0]}</Td>{r.slice(1).map((v,i)=><Td key={i}><span className={`grid size-8 place-items-center rounded ${Number(v)===0?"bg-destructive-soft text-destructive":Number(v)<4?"bg-warning-soft text-warning-foreground":"bg-success-soft text-success"}`}>{v}</span></Td>)}<Td><Button variant="ghost" size="sm">Update</Button></Td></tr>)}</tbody></TableWrap><div className="flex flex-wrap gap-4 p-4 text-xs text-muted-foreground"><span>Green: available</span><span>Amber: low inventory</span><span>Red: sold out / blocked</span></div></Card></>}
function BlockDialog(){return <Dialog><DialogTrigger asChild><Button>Block rooms</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Block selected rooms?</DialogTitle><DialogDescription>Blocked inventory cannot be booked until it is unblocked.</DialogDescription></DialogHeader><DialogFooter><DialogClose asChild><Button variant="outline">Go back</Button></DialogClose><DialogClose asChild><Button variant="destructive">Block rooms</Button></DialogClose></DialogFooter></DialogContent></Dialog>}

