export function PaymentsPage(){return <><PageIntro title="Payment Management" description="Track collections, pending transactions, failures, and refunds."/><div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-5">{[["Total Payments","₹18,42,500"],["Successful","2,614"],["Pending","83"],["Failed","41"],["Refunded","₹1,26,800"]].map(([n,v])=><Card key={n} className="p-4"><p className="text-xs text-muted-foreground">{n}</p><p className="mt-2 font-display text-xl font-semibold">{v}</p></Card>)}</div><FilterBar fields={["Transaction ID","Booking ID","Payment status"]}/><Card><TableWrap><thead><tr>{["Transaction ID","Booking ID","Customer","Amount","Payment Method","Date","Status"].map(x=><Th key={x}>{x}</Th>)}</tr></thead><tbody>{[["TXN-88921","BK-10245","Rahul Kumar","₹10,620","UPI","15 Sep 2026","Successful"],["TXN-88920","BK-10244","Priya Seshadri","₹21,400","Credit Card","15 Sep 2026","Pending"],["TXN-88919","BK-10243","Arjun Mehta","₹8,950","Net Banking","14 Sep 2026","Successful"],["TXN-88918","BK-10242","Sana Iyer","₹15,300","Credit Card","14 Sep 2026","Refunded"],["TXN-88917","BK-10241","Kiran Shah","₹6,450","UPI","14 Sep 2026","Failed"]].map(r=><tr key={r[0]}>{r.slice(0,6).map(v=><Td key={v}>{v}</Td>)}<Td><StatusBadge tone={tone(r[6])}>{r[6]}</StatusBadge></Td></tr>)}</tbody></TableWrap><Pagination/></Card></>}

export function ReportsPage(){return <><PageIntro title="Booking Reports" description="Analyze portfolio performance and export operational reports." actions={<><Button variant="outline"><FileText/>Export CSV</Button><Button><Download/>Export PDF</Button></>}/><FilterBar fields={["Date range","Hotel","Room","Booking status","Payment status"]}/><div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-5">{[["Total Bookings","2,845"],["Total Revenue","₹18,42,500"],["Avg. Booking Value","₹6,476"],["Cancellation Rate","10.8%"],["Occupancy Rate","78.4%"]].map(([n,v])=><Card key={n} className="p-4"><p className="text-xs text-muted-foreground">{n}</p><p className="mt-2 font-display text-xl font-semibold">{v}</p></Card>)}</div><Card><CardHead title="Revenue by Hotel" subtitle="Top five properties"/><div className="space-y-5 p-5">{[["Grand Palace Hotel","₹4,82,500",100],["Marina Bay Suites","₹3,94,200",82],["Azure Residency","₹3,12,800",65],["Veranda Grand","₹2,86,400",59],["The Fern Court","₹2,18,900",45]].map(([n,v,w])=><div key={n as string}><div className="mb-2 flex justify-between text-sm"><span>{n}</span><b>{v}</b></div><div className="h-3 rounded bg-muted"><div className="h-3 rounded bg-primary" style={{width:`${w}%`}}/></div></div>)}</div></Card></>}

function SettingRow({title,description,control}:{title:string;description:string;control:React.ReactNode}){return <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-4 border-b border-border py-4 last:border-0"><div><p className="text-sm font-medium">{title}</p><p className="mt-0.5 text-xs text-muted-foreground">{description}</p></div>{control}</div>}
export function SettingsPage(){const [email,setEmail]=useState(true);return <><PageIntro title="Settings" description="Configure booking rules, cancellations, payments, and notifications." actions={<Button><Save/>Save Changes</Button>}/><div className="grid gap-4 xl:grid-cols-2"><Card><CardHead title="Booking Settings"/><div className="px-5"><SettingRow title="Booking confirmation mode" description="Choose automatic or manual confirmation." control={<select className={inputClass}><option>Automatic</option><option>Manual</option></select>}/><SettingRow title="Minimum stay" description="Minimum nights per reservation." control={<input className={`${inputClass} w-24`} defaultValue="1 night"/>}/><SettingRow title="Maximum stay" description="Maximum nights per reservation." control={<input className={`${inputClass} w-24`} defaultValue="30 nights"/>}/><SettingRow title="Advance booking period" description="How far ahead guests can book." control={<input className={`${inputClass} w-28`} defaultValue="365 days"/>}/></div></Card><Card><CardHead title="Cancellation Settings"/><div className="px-5"><SettingRow title="Cancellation deadline" description="Free cancellation cut-off." control={<input className={`${inputClass} w-28`} defaultValue="48 hours"/>}/><SettingRow title="Cancellation fee" description="Fee after the free period." control={<input className={`${inputClass} w-24`} defaultValue="10%"/>}/><SettingRow title="Refund rules" description="Default policy for approved refunds." control={<select className={inputClass}><option>Original method</option><option>Wallet credit</option></select>}/></div></Card><Card><CardHead title="Payment Settings"/><div className="px-5"><SettingRow title="Payment methods" description="Cards, UPI, and net banking." control={<Switch defaultChecked/>}/><SettingRow title="Deposit percentage" description="Amount required to confirm." control={<input className={`${inputClass} w-24`} defaultValue="25%"/>}/><SettingRow title="Accept pending payments" description="Hold inventory while payment clears." control={<Switch/>}/></div></Card><Card><CardHead title="Notification Settings"/><div className="px-5"><SettingRow title="Booking confirmation email" description="Send when a booking is confirmed." control={<Switch checked={email} onCheckedChange={setEmail}/>}/><SettingRow title="Cancellation email" description="Send cancellation and refund details." control={<Switch defaultChecked/>}/><SettingRow title="Payment notification" description="Notify administrators of failures." control={<Switch defaultChecked/>}/><SettingRow title="Hotel notification" description="Notify properties of booking changes." control={<Switch defaultChecked/>}/></div></Card></div></>}